 function gifts(){openDialog('Your gift tree',`<p class="dialog-lead">Choose an equipment slot, then equip a gift. Power levels have no cap. Each upgrade costs one skill point; level-ups and story chapters award more.</p><p class="notice">${S.odyssey.skillPoints} skill points · Shift + 1–9 cycles Normal / Advance / Expert. These modes increase gift strength; Expert also hits all enemies. Steerable ground fields are not implemented in this edition.</p><label class="small muted">Equipment slot<select id="slotSelect">${S.equipped.map((id,i)=>`<option value="${i}" ${i===selectedSlot?'selected':''}>${i+1} · ${esc(C.gift(id).name)}</option>`).join('')}</select></label><div class="gift-list">${roster().map(id=>{const g=C.gift(id),unlocked=S.unlockedAbilities.includes(id);return`<div class="gift-item"><b>${esc(g.name)}</b><p>${esc(g.description)}</p><small>${g.element.toUpperCase()} · POWER ${S.giftPower[id]||0}</small><div style="margin-top:9px">${unlocked?`<button data-equip="${id}">Equip in slot ${selectedSlot+1}</button><button data-upgrade="${id}" ${S.odyssey.skillPoints<1?'disabled':''}>Train +1</button>`:`<button data-unlock="${id}" ${S.odyssey.skillPoints<1?'disabled':''}>Unlock · 1 point</button>`}</div></div>`}).join('')}</div>`)}
