 function saveMenuLegacy(){if(mode==='battle')return toast('Finish or retreat from the battle before saving or loading.');const data=storageRead(),rows=data.snapshots.filter(s=>s.profile===S.odyssey.profileId).slice(0,12);saveChoice=rows;openDialog('Keep your adventure safe',`<p class="dialog-lead">Device saves work offline. Exported files work across devices. A PIN works across devices only after a server snapshot is successfully saved and both devices open that same server.</p><div class="button-row"><button class="gold" data-do="saveNow">Save on this device</button><button data-do="export">Export backup JSON</button></div><div class="form" style="margin-top:20px"><label>Recovery PIN (4–12 digits; use a unique, longer PIN)<input id="pinInput" type="password" inputmode="numeric" autocomplete="off" maxlength="12" placeholder="Choose or enter your PIN"></label><div class="button-row"><button data-do="setPin">Set device PIN</button><button data-do="cloudSave">Save to this server</button></div></div><p class="notice" id="saveFeedback">${location.protocol==='file:'?'Offline file mode: server recovery is not available. Export a backup.':'Server saves are optional. A successful confirmation is required before relying on cross-device recovery.'}</p><h3 style="margin-top:22px">Timestamped recovery points</h3><div class="save-list">${rows.map((r,i)=>`<div class="save-row"><div><b>${esc(r.name)} · Lv ${r.level}</b><small>${new Date(r.at).toLocaleString()} · ${esc(r.label)}</small></div><button data-restore="${i}">Restore</button></div>`).join('')||'<p class="muted">No snapshots yet.</p>'}</div>`)}
 function recovery(){openDialog('Recover with your PIN',`<p class="dialog-lead">Search this device and, if available, this game’s save server. You choose which timestamp to load; a newer server save is never silently replaced by an older device save.</p><div class="form"><label>Recovery PIN<input id="recoverPin" type="password" inputmode="numeric" autocomplete="off" maxlength="12" placeholder="Your PIN"></label><button class="gold" data-do="findPin">Find recovery points</button></div><div id="recoveryResults" class="save-list"></div><p class="notice">A PIN cannot recover a save from a different, disconnected website. Keep your exported JSON backup.</p>`)}
 function validPin(pin){return/^\d{4,12}$/.test(pin)}
 async function api(path,body){if(window.MO_STATIC_HOST&&!window.MO_CLOUD_ENDPOINT)throw Error('This public site saves on your device. Online PIN recovery is not enabled yet. Use Export backup JSON to move progress between devices.');if(location.protocol==='file:')throw Error('This is an offline copy. Use an exported backup or open your game server.');const endpoint=window.MO_CLOUD_ENDPOINT||'';const r=await fetch(endpoint+'/api/'+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(20000)});if(!r.ok){let detail='Save server unavailable ('+r.status+').';try{detail=(await r.json()).error||detail}catch{}throw Error(detail)}return r.json()}
 async function findPin(){const pin=$('#recoverPin').value,results=$('#recoveryResults');if(!validPin(pin)){results.textContent='Enter a PIN of 4–12 digits.';return}results.textContent='Checking device and server recovery points…';let rows=storageRead().snapshots.filter(r=>r.data.save.pin===pin).map(r=>({...r,source:'This device'})),message='';if(window.CESAR_FIXTURE?.save.pin===pin)rows.push({name:'Cesar',level:34,at:CESAR_FIXTURE.exportedAt,data:C.clone(CESAR_FIXTURE),source:'Original Level-34 archive'});try{const remote=await api('recover',{pin});rows.push(...remote.snapshots.map(r=>({...r,source:'Save server'})))}catch(e){message=e.message}rows.sort((a,b)=>new Date(b.at)-new Date(a.at));saveChoice=rows;if(!results.isConnected)return;results.innerHTML=rows.map((r,i)=>`<div class="save-row"><div><b>${esc(r.name||r.data.save.name)} · Lv ${r.level||r.data.save.level}</b><small>${new Date(r.at).toLocaleString()} · ${esc(r.source)}</small></div><button data-restore="${i}">Load this snapshot</button></div>`).join('')||'<p class="muted">No matching saves were found here. Import your JSON backup if it came from another website.</p>';if(message)results.innerHTML+=`<p class="notice">${esc(message)} Device results above are still available.</p>`}
 async function cloudSaveLegacy(){const pin=$('#pinInput').value,feedback=$('#saveFeedback');if(!validPin(pin)){feedback.textContent='Enter a PIN of 4–12 digits.';return}S.pin=pin;checkpoint('Before server save');feedback.textContent='Saving a timestamped snapshot…';try{const data=serial(),r=await api('save',{pin,snapshot:{at:data.exportedAt,name:S.name,level:S.level,data}});if(feedback.isConnected)feedback.textContent='Saved to this server at '+new Date(r.at).toLocaleString()+'. Open this same server address on your other device and use PIN recovery.'}catch(e){if(feedback.isConnected)feedback.textContent=e.message+' Your device save is still available. Export a backup.'}}
 function newHero(){openDialog('A hero of your own',`<p class="dialog-lead">Cesar’s adventure will stay separate. Choose a name and a first gift for your own journey.</p><div class="form"><label>Hero name<input id="newName" maxlength="24" placeholder="Your hero’s name" autocomplete="off"></label><label>First gift<select id="newGift"><option value="elvinkin">Elvinkin · living flame</option><option value="shock-ring">Shock Ring · electricity</option><option value="worldheave">Worldheave · earth</option><option value="atom-choir">Atom Choir · light</option></select></label><button class="gold" data-do="createHero">Begin at Helix</button></div>`,'A NEW ARRIVAL')}
 function titleProfiles(){const data=storageRead(),rows=Object.values(data.profiles).sort((a,b)=>new Date(b.at)-new Date(a.at));if(!rows.length&&window.CESAR_FIXTURE){start(CESAR_FIXTURE);return}if(!rows.length)return newHero();saveChoice=rows;openDialog('Choose your adventure',`<div class="save-list">${rows.map((r,i)=>`<div class="save-row"><div><b>${esc(r.name)} · Lv ${r.level}</b><small>${new Date(r.at).toLocaleString()}</small></div><button data-restore="${i}" class="gold">Continue</button></div>`).join('')}</div>${window.CESAR_FIXTURE?'<div class="dialog-actions"><button data-do="original">Open original Cesar · Lv 34</button></div>':''}<p class="notice">Opening an older snapshot does not delete your other recovery points.</p>`)}
 $('#resume').onclick=titleProfiles;$('#newHero').onclick=newHero;$('#recover').onclick=recovery;$('#import').onclick=()=>$('#fileInput').click();$('#fileInput').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2_000_000)throw Error('Save file is too large.');const data=C.readSave(await file.text());if(active&&mode!=='battle')checkpoint('Before import');start(data)}catch(err){openDialog('Import needs attention',`<p class="dialog-lead">${esc(err.message)}</p><p class="muted">Your other adventures are unchanged.</p>`)}e.target.value=''};
