 function saveMenu(){if(mode==='battle')return toast('Finish or retreat from battle before saving.');const rows=storageRead().snapshots.filter(r=>r.profile===S.odyssey.profileId).slice(0,12);saveChoice=rows;openDialog('Save to your permanent website',`<p class="dialog-lead">Save online with a private PIN, then open this same website on your other device and choose PIN recovery. Keep your PIN private—anyone who knows it can recover your adventure.</p><p class="notice">Current hero: <b>${esc(S.name)} · Level ${S.level}</b>. Online saves keep the latest 24 timestamped recovery points. Use 8–12 digits, not a birthday.</p><div class="form"><label>Online recovery PIN<input id="pinInput" type="password" inputmode="numeric" autocomplete="off" maxlength="12" placeholder="8–12 private digits" value="${/^\d{8,12}$/.test(S.pin||'')?esc(S.pin):''}"></label><div class="button-row"><button class="gold" data-do="cloudSave">Save online now</button><button id="makePin">Generate a strong PIN</button></div><p id="generatedPin" class="notice" hidden></p></div><p id="saveFeedback" class="notice">Online save status: ${esc(S.odyssey.cloudSavedAt?'last confirmed '+new Date(S.odyssey.cloudSavedAt).toLocaleString():'not saved online yet')}.</p><div class="button-row"><button data-do="saveNow">Device backup</button><button data-do="export">Export backup JSON</button></div><h3 style="margin-top:20px">Device recovery points</h3><div class="save-list">${rows.map((r,i)=>`<div class="save-row"><div><b>${esc(r.name)} · Lv ${r.level}</b><small>${new Date(r.at).toLocaleString()}</small></div><button data-restore="${i}">Restore</button></div>`).join('')}</div>`);$('#makePin').onclick=()=>{const numbers=new Uint32Array(3);crypto.getRandomValues(numbers);const pin=Array.from(numbers,n=>String(n%10000).padStart(4,'0')).join('');$('#pinInput').value=pin;$('#generatedPin').hidden=false;$('#generatedPin').textContent='Write this PIN somewhere safe: '+pin+'. Then press Save online now.'}}
 let cloudBusy=false;
 async function cloudSave(){if(cloudBusy)return;const pin=$('#pinInput').value,feedback=$('#saveFeedback');if(!/^\d{8,12}$/.test(pin)){feedback.textContent='Online recovery needs 8–12 digits. Your original short PIN and device save are unchanged.';return}cloudBusy=true;feedback.textContent='Saving online… wait for confirmation.';const originalPin=S.pin;try{const data=serial();data.save.pin=pin;const r=await api('save',{pin,snapshot:{data}});S.pin=pin;S.odyssey.cloudSavedAt=r.at;checkpoint('Online save confirmed');if(feedback.isConnected)feedback.textContent='✓ Saved ONLINE: '+r.name+' · Level '+r.level+' · '+new Date(r.at).toLocaleString()+'. Recover with this PIN on the same website from another device.'}catch(e){S.pin=originalPin;if(feedback.isConnected)feedback.textContent=e.message+' Your device progress is unchanged.'}finally{cloudBusy=false}}

